using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.DependencyInjection;

namespace MyApp.Evaluations;

[TestClass]
public class ChatEvaluationTests
{
    private static DistributedApplicationTestingBuilder _appHost = null!;
    private static DistributedApplication _app = null!;

    [ClassInitialize]
    public static async Task ClassInitialize(TestContext context)
    {
        _appHost = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        _app = await _appHost.BuildAsync();
        await _app.StartAsync();
    }

    [ClassCleanup]
    public static async Task ClassCleanup()
    {
        if (_app is not null)
        {
            await _app.DisposeAsync();
        }
    }

    [TestMethod]
    public async Task Chat_RespondsRelevantly()
    {
        var chatClient = _app.Services.GetRequiredService<IChatClient>();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        var response = await chatClient.GetResponseAsync(messages);

        Assert.IsNotNull(response);
        Assert.IsTrue(response.Text.Contains("Paris", StringComparison.OrdinalIgnoreCase),
            "Expected the response to mention Paris.");
    }

    [TestMethod]
    public async Task Chat_Coherence_Evaluation()
    {
        var chatClient = _app.Services.GetRequiredService<IChatClient>();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Explain what cloud computing is in two sentences.")
        };

        var response = await chatClient.GetResponseAsync(messages);

        Assert.IsNotNull(response);
        Assert.IsFalse(string.IsNullOrWhiteSpace(response.Text),
            "Expected a non-empty response.");

        // Evaluate coherence using the AI evaluation framework
        var evaluator = new CoherenceEvaluator();
        var evalResult = await evaluator.EvaluateAsync(messages, response, chatClient);

        var coherenceScore = evalResult.Get<NumericMetricValue>(CoherenceEvaluator.CoherenceMetricName);
        Assert.IsNotNull(coherenceScore, "Coherence metric should be present.");
        Assert.IsTrue(coherenceScore.Value >= 3,
            $"Coherence score {coherenceScore.Value} is below the acceptable threshold of 3.");
    }

    [TestMethod]
    public async Task Chat_Relevance_Evaluation()
    {
        var chatClient = _app.Services.GetRequiredService<IChatClient>();

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What are the benefits of using containers in software development?")
        };

        var response = await chatClient.GetResponseAsync(messages);

        Assert.IsNotNull(response);

        var evaluator = new RelevanceEvaluator();
        var evalResult = await evaluator.EvaluateAsync(messages, response, chatClient);

        var relevanceScore = evalResult.Get<NumericMetricValue>(RelevanceEvaluator.RelevanceMetricName);
        Assert.IsNotNull(relevanceScore, "Relevance metric should be present.");
        Assert.IsTrue(relevanceScore.Value >= 3,
            $"Relevance score {relevanceScore.Value} is below the acceptable threshold of 3.");
    }
}

